 void LegacyAppsPage(){Header("Applications",catalog.Count+" launchable applications · your pins, then your full app library");var search=new TextBox{FontSize=15,Foreground=ink,Background=cardBrush,BorderThickness=new Thickness(0),Padding=new Thickness(14,12,14,12),Margin=new Thickness(0,0,0,12),ToolTip="Search applications"};page.Children.Add(search);var results=new StackPanel();page.Children.Add(results);Action fill=()=>{results.Children.Clear();string query=search.Text.Trim();AppSection(results,"Pinned to taskbar",DockEntries(),query,false);AppSection(results,"Pinned to this Start menu",cfg.StartPins,query,false);AppSection(results,"All applications",catalog,query,true);};search.TextChanged+=delegate{appPage=0;fill();};fill();page.Children.Add(Action("Refresh app library",async()=>{var p=Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+Path.Combine(Root,"Refresh-Apps.ps1")+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});await System.Threading.Tasks.Task.Run(()=>p.WaitForExit());p.Dispose();LoadCatalog();if(activeTab=="Apps")DrawLauncher();}));}
 void AppSection(StackPanel host,string heading,IEnumerable<AppEntry> entries,string query,bool canPin){var matched=entries.Where(a=>a.Name!=null&&a.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToList();host.Children.Add(new TextBlock{Text=heading+"  ·  "+matched.Count,Foreground=mutedBrush,FontSize=13,Margin=new Thickness(0,14,0,8)});if(matched.Count==0){host.Children.Add(Text(query.Length>0?"No matches":"—",11,mutedBrush));return;}if(canPin){int pages=Math.Max(1,(matched.Count+19)/20);appPage=Math.Min(appPage,pages-1);var nav=new StackPanel{Orientation=Orientation.Horizontal};nav.Children.Add(Action("← Previous",()=>{appPage=Math.Max(0,appPage-1);DrawLauncher();}));nav.Children.Add(Text("  Page "+(appPage+1)+" / "+pages+"  ",12,mutedBrush));nav.Children.Add(Action("Next →",()=>{appPage=Math.Min(pages-1,appPage+1);DrawLauncher();}));host.Children.Add(nav);matched=matched.Skip(appPage*20).Take(20).ToList();}foreach(var app in matched){var entry=app;var row=new Grid{Margin=new Thickness(0,2,0,2),Background=cardBrush};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var open=Action("",()=>OpenApp(entry));open.Background=Brushes.Transparent;var content=new StackPanel{Orientation=Orientation.Horizontal};var image=new Image{Width=34,Height=34,Margin=new Thickness(0,0,12,0)};QueueIcon(image,entry.Target);content.Children.Add(image);var label=Text(entry.Name,13);label.MaxWidth=310;label.TextTrimming=TextTrimming.CharacterEllipsis;label.TextWrapping=TextWrapping.NoWrap;content.Children.Add(label);open.Content=content;open.HorizontalContentAlignment=HorizontalAlignment.Left;row.Children.Add(open);var actions=new StackPanel{Orientation=Orientation.Horizontal};Grid.SetColumn(actions,1);bool pinned=cfg.StartPins.Any(x=>x.Target==entry.Target);actions.Children.Add(Action(pinned?"★ Start":"☆ Start",()=>{if(pinned)cfg.StartPins.RemoveAll(x=>x.Target==entry.Target);else cfg.StartPins.Add(entry);Changed();},pinned));if(canPin){bool dockPin=cfg.DockPins.Any(x=>x.Target==entry.Target);actions.Children.Add(Action(dockPin?"− Dock":"+ Dock",()=>{if(dockPin)cfg.DockPins.RemoveAll(x=>x.Target==entry.Target);else cfg.DockPins.Add(entry);Changed();},dockPin));}else if(cfg.DockPins.Any(x=>x.Target==entry.Target))actions.Children.Add(Action("− Dock",()=>{cfg.DockPins.RemoveAll(x=>x.Target==entry.Target);Changed();}));row.Children.Add(actions);host.Children.Add(row);}}
 void LegacyGeneralPage(){Header("General","Your launcher, your defaults.");string startup=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"Awl.lnk");Toggle("Start when I sign in",File.Exists(startup),v=>{if(v)Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+Path.Combine(Root,"Enable-Startup.ps1")+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});else File.Delete(startup);var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(800)};timer.Tick+=delegate{timer.Stop();DrawLauncher();};timer.Start();});Toggle("Close launcher when focus moves away",cfg.CloseOnBlur,v=>{cfg.CloseOnBlur=v;Changed();});Section("Everyday shortcuts");page.Children.Add(Action("Open Windows Start",()=>{launcher.Hide();Native.StartMenu();}));page.Children.Add(Action("Open user folder",()=>Launch(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile))));page.Children.Add(Action("Open customization folder",()=>Launch(Root)));Section("Restore");page.Children.Add(Action("Exit & restore Windows taskbar",()=>Quit()));}
